<template>
<div class="container-fluid pb-4">
    <div class="card shadow-sm mb-3"><div class="card-body py-3">
        <div class="row align-items-end">
            <div class="col-md-4"><label class="font-weight-bold">分析維度</label><div class="btn-group btn-group-toggle d-flex">
                <button class="btn flex-fill" :class="dimension==='customer'?'btn-primary':'btn-outline-primary'" @click="setDimension('customer')">顧客</button>
                <button class="btn flex-fill" :class="dimension==='product'?'btn-primary':'btn-outline-primary'" @click="setDimension('product')">商品</button>
            </div></div>
            <div class="col-md-4"><label class="font-weight-bold">金額口徑</label><select v-model="amountBasis" class="form-control" @change="refresh"><option value="pre_tax">未稅淨銷售額</option><option value="tax_inclusive">含稅淨銷售額</option></select></div>
            <div class="col-md-4 text-md-right mt-3 mt-md-0"><button class="btn btn-outline-success mr-2" :disabled="!canExport" @click="exportCsv">匯出 CSV</button><button class="btn btn-outline-danger" :disabled="!canExport || exporting" @click="exportPdf">{{ exporting ? '產生中…' : '匯出 PDF' }}</button></div>
        </div>
    </div></div>

    <ul class="nav nav-tabs mb-3">
        <li class="nav-item" v-for="item in tabs" :key="item.id"><a href="#" class="nav-link" :class="{active:tab===item.id}" @click.prevent="setTab(item.id)">{{ item.label }}</a></li>
    </ul>
    <div v-if="error" class="alert alert-danger">{{ error }}</div>

    <div v-if="tab==='overview'">
        <div class="card mb-3"><div class="card-body"><div class="form-row align-items-end">
            <div class="col-md-2"><label>期間模式</label><select v-model="overview.periodMode" class="form-control" @change="normalizeOverviewMonths"><option value="year">整年</option><option value="month">單月</option><option value="range">月份區間</option></select></div>
            <div class="col-md-2"><label>年度</label><select v-model.number="overview.year" class="form-control" @change="normalizeOverviewMonths"><option v-for="year in years" :key="year" :value="year">{{ year }}</option></select></div>
            <div v-if="overview.periodMode==='month'" class="col-md-2"><label>月份</label><select v-model.number="overview.month" class="form-control"><option v-for="m in maxMonthForYear(overview.year)" :key="m" :value="m">{{m}} 月</option></select></div>
            <template v-else-if="overview.periodMode==='range'"><div class="col-md-2"><label>起始月</label><select v-model.number="overview.startMonth" class="form-control"><option v-for="m in maxMonthForYear(overview.year)" :key="m" :value="m">{{m}} 月</option></select></div><div class="col-md-2"><label>結束月</label><select v-model.number="overview.endMonth" class="form-control"><option v-for="m in maxMonthForYear(overview.year)" :key="m" :value="m">{{m}} 月</option></select></div></template>
            <div class="col-md-2"><label>排序</label><select v-model="overview.sort" class="form-control"><option value="desc">銷售額由高至低</option><option value="asc">銷售額由低至高</option></select></div>
            <div class="col-md-2"><div class="custom-control custom-switch mb-2"><input id="excludeZero" v-model="overview.excludeZero" type="checkbox" class="custom-control-input"><label for="excludeZero" class="custom-control-label">隱藏無銷售紀錄</label></div></div>
            <div class="col-md-2"><button class="btn btn-primary btn-block" :disabled="!overviewPeriodValid" @click="loadOverview">查詢</button></div>
        </div></div></div>
        <report-chart v-if="result" ref="reportChart" :chart-data="result.chart" chart-type="bar" title="Top 10 銷售排行"></report-chart>
        <div v-if="result" class="card shadow-sm"><div class="card-header bg-white"><strong>{{ result.period.label }}</strong></div><div class="card-body table-responsive p-0"><table class="table table-sm table-hover table-bordered mb-0 sales-table"><thead><tr><th class="sticky-name">{{ entityLabel }}</th><th v-for="m in overviewDisplayMonths" :key="m">{{m}}月</th><th>{{result.total_label}}</th></tr></thead><tbody>
            <tr v-for="row in result.rows" :key="row.entity.id" class="clickable" @click="drillFrom(row)"><td class="sticky-name">{{row.entity.name}} <span v-if="row.entity.is_deleted" class="badge badge-secondary">已停用</span></td><td v-for="m in overviewDisplayMonths" :key="m" class="text-right">{{money(row.months[m-1])}}</td><td class="text-right font-weight-bold">{{money(row.total)}}</td></tr>
            <tr class="font-weight-bold table-secondary"><td class="sticky-name">總計</td><td v-for="m in overviewDisplayMonths" :key="m" class="text-right">{{money(result.totals.months[m-1])}}</td><td class="text-right">{{money(result.totals.total)}}</td></tr>
        </tbody></table></div></div>
    </div>

    <div v-else-if="tab==='drilldown'">
        <div class="card mb-3"><div class="card-body">
            <div class="form-row"><div class="col-md-6"><label>{{entityLabel}}</label><entity-search v-model="drill.entity" :dimension="dimension" :url="urls.entities" @input="clearResult"></entity-search></div>
            <div class="col-md-6"><label>分析模式</label><select v-model="drill.mode" class="form-control" @change="clearResult"><option value="annual">單年度月份分解</option><option value="trend">歷年趨勢</option><option value="comparison">跨年同期比較</option></select></div></div>
            <div class="form-row mt-3 align-items-end" v-if="drill.mode==='annual'"><div class="col-md-3"><label>年度</label><select v-model.number="drill.year" class="form-control" @change="normalizeDrillMonths"><option v-for="y in years" :key="y" :value="y">{{y}}</option></select></div><div class="col-md-2"><label>起始月</label><select v-model.number="drill.startMonth" class="form-control"><option v-for="m in maxMonthForYear(drill.year)" :key="m" :value="m">{{m}} 月</option></select></div><div class="col-md-2"><label>結束月</label><select v-model.number="drill.endMonth" class="form-control"><option v-for="m in maxMonthForYear(drill.year)" :key="m" :value="m">{{m}} 月</option></select></div><div class="col-md-3 offset-md-2"><button class="btn btn-primary btn-block" :disabled="!drill.entity || drill.startMonth>drill.endMonth" @click="loadDrill">查詢</button></div></div>
            <div class="form-row mt-3 align-items-end" v-else-if="drill.mode==='trend'"><div class="col-md-4"><label>範圍</label><select v-model="drill.recentYears" class="form-control"><option value="3">近 3 年</option><option value="5">近 5 年</option><option value="10">近 10 年</option><option value="all">全部年度</option></select></div><div class="col-md-4 offset-md-4"><button class="btn btn-primary btn-block" :disabled="!drill.entity" @click="loadDrill">查詢</button></div></div>
            <div class="form-row mt-3 align-items-end" v-else><div class="col-md-2"><label>年度 A</label><select v-model.number="drill.yearA" class="form-control" @change="normalizeComparisonMonths"><option v-for="y in years" :key="y" :value="y">{{y}}</option></select></div><div class="col-md-2"><label>年度 B</label><select v-model.number="drill.yearB" class="form-control" @change="normalizeComparisonMonths"><option v-for="y in years" :key="y" :value="y">{{y}}</option></select></div><div class="col-md-2"><label>起始月</label><select v-model.number="drill.startMonth" class="form-control"><option v-for="m in comparisonMaxMonth" :key="m" :value="m">{{m}}</option></select></div><div class="col-md-2"><label>結束月</label><select v-model.number="drill.endMonth" class="form-control"><option v-for="m in comparisonMaxMonth" :key="m" :value="m">{{m}}</option></select></div><div class="col-md-4"><button class="btn btn-primary btn-block" :disabled="!drill.entity || drill.yearA===drill.yearB || drill.startMonth>drill.endMonth" @click="loadDrill">查詢</button></div></div>
        </div></div>
        <div v-if="result && result.kpis" class="row mb-3"><div class="col-md-4" v-for="k in kpis" :key="k.label"><div class="card border-left-primary shadow-sm h-100"><div class="card-body"><div class="text-muted">{{k.label}}</div><div class="h4 mb-0">{{k.value}}</div></div></div></div></div>
        <report-chart v-if="result" ref="reportChart" :chart-data="result.chart" :chart-type="drill.mode==='trend'?'line':'bar'" :title="result.entity.name"></report-chart>
        <div v-if="result" class="card shadow-sm drill-table-card">
            <div class="card-header bg-white d-flex flex-wrap justify-content-between align-items-center">
                <div><strong>{{ drillTableTitle }}</strong><div class="small text-muted mt-1">{{ result.entity.name }}／{{ drillPeriodLabel }}／{{ amountBasis==='pre_tax'?'未稅淨銷售額':'含稅淨銷售額' }}</div></div>
                <span class="badge badge-light border mt-2 mt-sm-0">共 {{ result.rows.length }} 筆</span>
            </div>
            <div class="table-responsive"><table class="table table-striped table-hover mb-0 drill-table"><thead class="thead-light"><tr v-if="drill.mode==='comparison'"><th>月份</th><th class="text-right">{{drill.yearA}} 年</th><th class="text-right">{{drill.yearB}} 年</th><th class="text-right">差異</th><th class="text-right">差異百分比</th></tr><tr v-else><th>{{drill.mode==='trend'?'年度':'月份'}}</th><th class="text-right">銷售額</th></tr></thead><tbody>
                <tr v-for="row in result.rows" :key="drill.mode==='trend'?row.year:row.month"><template v-if="drill.mode==='comparison'"><td><span class="month-pill">{{row.month}} 月</span></td><td class="text-right amount-cell">{{money(row.year_a_amount)}}</td><td class="text-right amount-cell">{{money(row.year_b_amount)}}</td><td class="text-right font-weight-bold" :class="trendClass(row.percent)">{{money(row.difference)}}</td><td class="text-right"><span class="trend-badge" :class="trendClass(row.percent)">{{trendLabel(row.percent)}}</span></td></template><template v-else><td><span class="month-pill">{{drill.mode==='trend'?row.year+' 年':row.month+' 月'}}</span></td><td class="text-right amount-cell font-weight-bold">{{money(row.amount)}}</td></template></tr>
            </tbody></table></div>
        </div>
    </div>

    <div v-else>
        <div class="card mb-3"><div class="card-body"><div class="form-row">
            <div class="col-md-4"><label>{{entityLabel}}（選填）</label><entity-search v-model="detail.entity" :dimension="dimension" :url="urls.entities" @input="clearResult"></entity-search></div>
            <div class="col-md-2"><label>起日</label><input v-model="detail.startDate" type="date" class="form-control"></div><div class="col-md-2"><label>迄日</label><input v-model="detail.endDate" type="date" class="form-control"></div>
            <div class="col-md-2"><label>日期依據</label><select v-model="detail.dateBasis" class="form-control"><option value="transaction">交易日期</option><option value="delivered">出貨日期</option><option value="paid">付款日期</option><option value="created">建立日期</option></select></div>
            <div class="col-md-2"><label>狀態</label><select v-model="detail.orderStatus" class="form-control"><option value="all">全部</option><option value="unpaid">未付款</option><option value="paid">已付款</option><option value="undelivered">未出貨</option><option value="completed">已完成</option></select></div>
        </div><div class="form-row mt-3 align-items-end"><div class="col-md-2"><label>每頁</label><select v-model.number="detail.perPage" class="form-control"><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select></div><div class="col-md-3 offset-md-7"><button class="btn btn-primary btn-block" @click="loadDetails(1)">查詢</button></div></div></div></div>
        <div v-if="result" class="card"><div class="card-header d-flex justify-content-between"><span>共 {{result.summary.row_count}} 筆明細／{{result.summary.order_count}} 張單</span><strong>總數量 {{number(result.summary.quantity)}}；總金額 {{money(result.summary.amount)}}</strong></div><div class="table-responsive"><table class="table table-sm table-hover table-bordered mb-0"><thead><tr><th v-for="column in detailColumns" :key="column.key" @click="sortDetail(column.key)" :class="column.sortable?'clickable':''">{{column.label}} <span v-if="detail.sortBy===column.key">{{detail.sortDirection==='asc'?'▲':'▼'}}</span></th></tr></thead><tbody><tr v-for="row in result.rows" :key="row.id"><td><a :href="row.show_url" target="_blank">{{row.shown_id}}</a></td><td>{{row.transaction_date}}</td><td>{{row.order_type}}</td><td>{{row.customer_name}}</td><td>{{row.product_code}}</td><td>{{row.product_name}}</td><td>{{row.unit}}</td><td class="text-right">{{number(row.quantity)}}</td><td class="text-right">{{money(row.price)}}</td><td class="text-right">{{number(row.discount)}}</td><td class="text-right">{{money(row.amount)}}</td></tr></tbody></table></div>
            <div class="card-footer d-flex justify-content-between align-items-center"><span>第 {{result.pagination.current_page}} / {{result.pagination.last_page}} 頁</span><div><button class="btn btn-sm btn-outline-secondary mr-2" :disabled="result.pagination.current_page<=1" @click="loadDetails(result.pagination.current_page-1)">上一頁</button><button class="btn btn-sm btn-outline-secondary" :disabled="result.pagination.current_page>=result.pagination.last_page" @click="loadDetails(result.pagination.current_page+1)">下一頁</button></div></div>
        </div>
    </div>
    <div v-if="loading" class="analysis-loading"><div class="spinner-border text-primary"></div></div>
</div>
</template>

<script>
import EntitySearch from './SalesAnalysisEntitySearch.vue';

const ReportChart = {
    props: ['chartData','chartType','title'], template: '<div class="card shadow-sm mb-3"><div class="card-header">{{title}}</div><div class="card-body chart-wrap"><canvas ref="canvas"></canvas></div></div>',
    data() { return { instance: null }; }, mounted() { this.draw(); }, watch: { chartData: { deep:true, handler() { this.draw(); } } }, beforeDestroy() { if(this.instance) this.instance.destroy(); },
    methods: { draw() { this.$nextTick(() => { if(this.instance) this.instance.destroy(); const raw=this.chartData; const data=raw.datasets ? raw : {labels:raw.map(x=>x.label),datasets:[{label:'銷售額',data:raw.map(x=>x.value)}]}; this.instance=new Chart(this.$refs.canvas.getContext('2d'),{type:this.chartType||'bar',data:{labels:data.labels,datasets:data.datasets.map((d,i)=>Object.assign({},d,{backgroundColor:i?'rgba(28,200,138,.35)':'rgba(78,115,223,.45)',borderColor:i?'#1cc88a':'#4e73df',borderWidth:2,fill:false}))},options:{maintainAspectRatio:false,tooltips:{callbacks:{label:(item,d)=>d.datasets[item.datasetIndex].label+': '+Number(item.yLabel).toLocaleString('zh-TW',{maximumFractionDigits:2})}},scales:{yAxes:[{ticks:{beginAtZero:true,callback:v=>Number(v).toLocaleString()}}]}}}); }); }, image() { return this.instance ? this.instance.toBase64Image() : null; } }
};

export default {
    props: { urls: Object }, components: { EntitySearch, ReportChart },
    data() { const now=new Date(), pad=n=>String(n).padStart(2,'0'), currentMonth=now.getMonth()+1; return { loading:false, exporting:false, error:'', meta:null, tab:'overview', dimension:'customer', amountBasis:'pre_tax', result:null, tabs:[{id:'overview',label:'總覽 Overview'},{id:'drilldown',label:'單一分析 Drill-down'},{id:'detail',label:'明細查詢 Detail'}], overview:{periodMode:'year',year:now.getFullYear(),month:currentMonth,startMonth:1,endMonth:currentMonth,sort:'desc',excludeZero:true}, drill:{entity:null,mode:'annual',year:now.getFullYear(),recentYears:'5',yearA:now.getFullYear(),yearB:now.getFullYear()-1,startMonth:1,endMonth:currentMonth}, detail:{entity:null,startDate:now.getFullYear()+'-'+pad(currentMonth)+'-01',endDate:now.getFullYear()+'-'+pad(currentMonth)+'-'+pad(now.getDate()),dateBasis:'transaction',orderStatus:'all',sortBy:'transaction_date',sortDirection:'desc',perPage:50,page:1}, detailColumns:[{key:'shown_id',label:'銷貨單號',sortable:true},{key:'transaction_date',label:'日期',sortable:true},{key:'order_type',label:'單別'},{key:'customer_name',label:'顧客',sortable:true},{key:'product_code',label:'商品編號'},{key:'product_name',label:'商品',sortable:true},{key:'unit',label:'單位'},{key:'quantity',label:'數量',sortable:true},{key:'price',label:'單價'},{key:'discount',label:'折數'},{key:'amount',label:'金額',sortable:true}] }; },
    computed: { years() { return this.meta ? this.meta.years.slice().reverse() : [new Date().getFullYear()]; }, entityLabel() { return this.dimension==='customer'?'顧客':'商品'; }, overviewDisplayMonths() { return this.result && this.result.display_months ? this.result.display_months : Array.from({length:12},(_,i)=>i+1); }, overviewPeriodValid() { return this.overview.periodMode!=='range'||this.overview.startMonth<=this.overview.endMonth; }, comparisonMaxMonth() { return Math.min(this.maxMonthForYear(this.drill.yearA),this.maxMonthForYear(this.drill.yearB)); }, drillPeriodLabel() { return !this.result?'':this.result.period?this.result.period.label:(this.result.period_label||''); }, drillTableTitle() { return this.drill.mode==='comparison'?'跨年同期比較':this.drill.mode==='trend'?'歷年銷售趨勢':'單年度月份明細'; }, canExport() { return !!this.result && (this.tab!=='drilldown'||!!this.drill.entity); }, kpis() { if(!this.result||!this.result.kpis)return[]; const count=this.result.period?this.result.period.months.length:12; return [{label:'區間總銷售額',value:this.money(this.result.kpis.total)},{label:'平均月銷售額（÷'+count+'）',value:this.money(this.result.kpis.monthly_average)},{label:'占全體區間淨營收',value:this.result.kpis.revenue_share.toFixed(2)+'%'}]; } },
    mounted() { axios.get(this.urls.meta).then(({data})=>{this.meta=data; return this.restore();}).catch(this.fail); },
    methods: {
        number(v) { return Number(v||0).toLocaleString('zh-TW',{maximumFractionDigits:2}); }, money(v) { return '$'+this.number(v); }, trendClass(percent) { return percent===null?'trend-na':percent>0?'trend-up':percent<0?'trend-down':'trend-flat'; }, trendLabel(percent) { return percent===null?'N/A':percent>0?'▲ '+percent.toFixed(2)+'%':percent<0?'▼ '+Math.abs(percent).toFixed(2)+'%':'0.00%'; }, fail(e) { this.error=(e.response&&e.response.data&&(e.response.data.message||Object.values(e.response.data.errors||{})[0]))||'資料讀取失敗'; this.loading=false; },
        setDimension(value) { if(this.dimension===value)return; this.dimension=value; this.drill.entity=null; this.detail.entity=null; this.result=null; this.refresh(); },
        setTab(value) { this.tab=value; this.result=null; this.refresh(); }, clearResult() { this.result=null; this.syncUrl(); }, refresh() { if(this.tab==='overview')this.loadOverview(); else if(this.tab==='drilldown'&&this.drill.entity)this.loadDrill(); else if(this.tab==='detail')this.loadDetails(1); else this.syncUrl(); },
        base() { return {dimension:this.dimension,amount_basis:this.amountBasis}; },
        maxMonthForYear(year) { const now=new Date(); return Number(year)===now.getFullYear()?now.getMonth()+1:12; },
        normalizeOverviewMonths() { const max=this.maxMonthForYear(this.overview.year); this.overview.month=Math.min(this.overview.month,max); this.overview.startMonth=Math.min(this.overview.startMonth,max); this.overview.endMonth=Math.min(this.overview.endMonth,max); if(this.overview.startMonth>this.overview.endMonth)this.overview.startMonth=this.overview.endMonth; this.clearResult(); },
        normalizeDrillMonths() { const max=this.maxMonthForYear(this.drill.year); this.drill.startMonth=Math.min(this.drill.startMonth,max); this.drill.endMonth=Math.min(this.drill.endMonth,max); if(this.drill.startMonth>this.drill.endMonth)this.drill.startMonth=this.drill.endMonth; this.clearResult(); },
        normalizeComparisonMonths() { const max=this.comparisonMaxMonth; this.drill.startMonth=Math.min(this.drill.startMonth,max); this.drill.endMonth=Math.min(this.drill.endMonth,max); if(this.drill.startMonth>this.drill.endMonth)this.drill.startMonth=this.drill.endMonth; this.clearResult(); },
        overviewParams() { const p=Object.assign(this.base(),{period_mode:this.overview.periodMode,year:this.overview.year,sort:this.overview.sort,exclude_zero:this.overview.excludeZero?1:0}); if(this.overview.periodMode==='month')p.month=this.overview.month; else if(this.overview.periodMode==='range')Object.assign(p,{start_month:this.overview.startMonth,end_month:this.overview.endMonth}); return p; },
        drillParams() { const p=Object.assign(this.base(),{entity_id:this.drill.entity&&this.drill.entity.id,mode:this.drill.mode}); if(this.drill.mode==='annual')Object.assign(p,{year:this.drill.year,start_month:this.drill.startMonth,end_month:this.drill.endMonth}); else if(this.drill.mode==='trend')p.recent_years=this.drill.recentYears; else Object.assign(p,{year_a:this.drill.yearA,year_b:this.drill.yearB,start_month:this.drill.startMonth,end_month:this.drill.endMonth}); return p; },
        detailParams(page) { return Object.assign(this.base(),{entity_id:this.detail.entity&&this.detail.entity.id,start_date:this.detail.startDate,end_date:this.detail.endDate,date_basis:this.detail.dateBasis,order_status:this.detail.orderStatus,sort_by:this.detail.sortBy,sort_direction:this.detail.sortDirection,per_page:this.detail.perPage,page:page||this.detail.page}); },
        request(url,params) { this.loading=true; this.error=''; return axios.get(url,{params}).then(({data})=>{this.result=data;this.syncUrl();}).catch(this.fail).finally(()=>{this.loading=false;}); },
        loadOverview() { return this.request(this.urls.overview,this.overviewParams()); }, loadDrill() { if(this.drill.mode==='comparison'&&this.drill.yearA===this.drill.yearB){this.error='比較年度不得相同';return;} return this.request(this.urls.drilldown,this.drillParams()); }, loadDetails(page) { this.detail.page=page; return this.request(this.urls.details,this.detailParams(page)); },
        drillFrom(row) { this.drill.entity=row.entity; this.drill.year=this.overview.year; this.drill.startMonth=this.result.period.start_month; this.drill.endMonth=this.result.period.end_month; this.drill.mode='annual'; this.tab='drilldown'; this.loadDrill(); },
        sortDetail(key) { const column=this.detailColumns.find(c=>c.key===key); if(!column||!column.sortable)return; if(this.detail.sortBy===key)this.detail.sortDirection=this.detail.sortDirection==='asc'?'desc':'asc'; else {this.detail.sortBy=key;this.detail.sortDirection='asc';} this.loadDetails(1); },
        exportParams() { return Object.assign({tab:this.tab},this.tab==='overview'?this.overviewParams():this.tab==='drilldown'?this.drillParams():this.detailParams(1)); },
        exportCsv() { const q=new URLSearchParams(); Object.entries(this.exportParams()).forEach(([k,v])=>{if(v!==null&&v!==undefined)q.set(k,v);}); window.location=this.urls.csv+'?'+q.toString(); },
        exportPdf() { this.exporting=true; const p=this.exportParams(); if(this.$refs.reportChart)p.chart_image=this.$refs.reportChart.image(); axios.post(this.urls.pdf,p,{responseType:'blob'}).then(res=>{const u=URL.createObjectURL(res.data),a=document.createElement('a'),encoded=res.headers['x-export-filename'];a.href=u;a.download=encoded?decodeURIComponent(encoded):'銷售分析.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}).catch(async e=>{if(e.response&&e.response.data instanceof Blob){try{const j=JSON.parse(await e.response.data.text());this.error=j.message;}catch(x){this.error='PDF 匯出失敗';}}else this.fail(e);}).finally(()=>{this.exporting=false;}); },
        syncUrl() { const p=this.exportParams(); delete p.tab; const q=new URLSearchParams(); q.set('tab',this.tab); Object.entries(p).forEach(([k,v])=>{if(v!==null&&v!==undefined)q.set(k,v);}); history.replaceState(null,'',location.pathname+'?'+q.toString()); },
        async restoreEntity(id,target) { if(!id)return; const {data}=await axios.get(this.urls.entities,{params:{dimension:this.dimension,id,per_page:20,page:1}}); if(data.data.length)this[target].entity=data.data[0]; },
        async restore() { const q=new URLSearchParams(location.search); this.tab=['overview','drilldown','detail'].includes(q.get('tab'))?q.get('tab'):'overview'; this.dimension=['customer','product'].includes(q.get('dimension'))?q.get('dimension'):'customer'; this.amountBasis=q.get('amount_basis')==='tax_inclusive'?'tax_inclusive':'pre_tax'; const n=(k,d)=>q.has(k)?Number(q.get(k)):d; this.overview.periodMode=['year','month','range'].includes(q.get('period_mode'))?q.get('period_mode'):'year';this.overview.year=n('year',this.overview.year);this.overview.month=n('month',this.overview.month);this.overview.startMonth=n('start_month',this.overview.startMonth);this.overview.endMonth=n('end_month',this.maxMonthForYear(this.overview.year));this.overview.sort=q.get('sort')==='asc'?'asc':'desc';this.overview.excludeZero=q.get('exclude_zero')!=='0';if(this.tab==='overview'){const max=this.maxMonthForYear(this.overview.year);this.overview.month=Math.min(this.overview.month,max);this.overview.endMonth=Math.min(this.overview.endMonth,max);} if(this.tab==='drilldown'){this.drill.mode=['annual','trend','comparison'].includes(q.get('mode'))?q.get('mode'):'annual';this.drill.year=n('year',this.drill.year);this.drill.recentYears=q.get('recent_years')||'5';this.drill.yearA=n('year_a',this.drill.yearA);this.drill.yearB=n('year_b',this.drill.yearB);this.drill.startMonth=n('start_month',1);this.drill.endMonth=n('end_month',this.drill.mode==='comparison'?this.comparisonMaxMonth:this.maxMonthForYear(this.drill.year));await this.restoreEntity(q.get('entity_id'),'drill');} if(this.tab==='detail'){this.detail.startDate=q.get('start_date')||this.detail.startDate;this.detail.endDate=q.get('end_date')||this.detail.endDate;this.detail.dateBasis=q.get('date_basis')||'transaction';this.detail.orderStatus=q.get('order_status')||'all';this.detail.sortBy=q.get('sort_by')||'transaction_date';this.detail.sortDirection=q.get('sort_direction')==='asc'?'asc':'desc';this.detail.perPage=n('per_page',50);this.detail.page=n('page',1);await this.restoreEntity(q.get('entity_id'),'detail');} this.refresh(); }
    }
};
</script>

